class MemoryGuard {
    int* data;
public:
    explicit MemoryGuard(size_t s) : data(new int[s]) {}
    // Disable copying (Rule of Three/Five implication for RAII)
    MemoryGuard(const MemoryGuard&) = delete;

    ~MemoryGuard() { 
        delete[] data; // Guaranteed cleanup
    }
};

