class MutexLocker {
    Mutex& m_ref;
public:
    explicit MutexLocker(Mutex& m) : m_ref(m) {
        m_ref.lock();   // Lock acquired
    }
    ~MutexLocker() {
        m_ref.unlock(); // Lock released (even on exception)
    }
};
